import{describe,it,expect,beforeEach}from"vitest";import{SilhouetteGame}from"../../frontend/state-silhouette-guessing/script.js";const mockLocations=[{id:"mh",name:"Maharashtra",capital:"Mumbai",path:"M 10 10 L 20 20 Z"},{id:"dl",name:"Delhi",capital:"New Delhi",path:"M 30 30 L 40 40 Z"},{id:"tn",name:"Tamil Nadu",capital:"Chennai",path:"M 50 50 L 60 60 Z"},{id:"rj",name:"Rajasthan",capital:"Jaipur",path:"M 70 70 L 80 80 Z"},{id:"ka",name:"Karnataka",capital:"Bengaluru",path:"M 90 90 L 100 100 Z"}];describe("State Silhouette Guessing Game Logic",()=>{let e;beforeEach(()=>{localStorage.clear(),e=new SilhouetteGame(mockLocations)}),it("should initialize game stats properly",()=>{expect(e.score).toBe(0),expect(e.streak).toBe(0),expect(e.bestStreak).toBe(0),expect(e.played).toBe(0)}),it("should select a random target state and 4 options",()=>{const t=e.startNewRound();expect(t.target).toBeDefined(),expect(mockLocations).toContainEqual(t.target),expect(t.options.length).toBe(4),expect(t.options).toContainEqual(t.target)}),it("should accurately validate correct user guess and update streak/score",()=>{e.startNewRound();const t=e.currentTarget.name,a=e.checkAnswer(t);expect(a.isCorrect).toBe(!0),expect(e.score).toBe(10),expect(e.streak).toBe(1),expect(e.bestStreak).toBe(1)}),it("should reset streak on incorrect answer",()=>{e.startNewRound(),e.checkAnswer(e.currentTarget.name),e.startNewRound();const t=e.checkAnswer("NonExistentState");expect(t.isCorrect).toBe(!1),expect(e.streak).toBe(0),expect(e.bestStreak).toBe(1)}),it("should award fewer points when hint is used",()=>{e.startNewRound();const t=e.getHint();expect(t).toContain("Capital City:");const a=e.checkAnswer(e.currentTarget.name);expect(a.isCorrect).toBe(!0),expect(e.score).toBe(5)}),it("should reset stats correctly",()=>{e.startNewRound(),e.checkAnswer(e.currentTarget.name),expect(e.score).toBe(10),e.resetStats(),expect(e.score).toBe(0),expect(e.streak).toBe(0),expect(e.bestStreak).toBe(0)})});